export interface ConnectorConfig {
  /** HubSpot private app access token or API key for CRM API calls. */
  hubspotApiKey: string
  /** Base URL for HubSpot API. Defaults to 'https://api.hubapi.com'. */
  hubspotBaseUrl?: string
  /** Stripe secret key for Bearer authentication. */
  stripeSecretKey: string
  /** Injected fetch for testing. */
  fetch?: typeof fetch
}

export interface HubSpotWebhookEvent {
  appId: number
  eventId: number
  subscriptionId: number
  portalId: number
  occurredAt: number
  subscriptionType: string
  attemptNumber: number
  objectId: number
  changeSource: string
  objectTypeId: string
  propertyName: string
  propertyValue: string
  isSensitive: boolean
}

export type HubSpotWebhookPayload = HubSpotWebhookEvent[]

export interface HubSpotContact {
  id: string
  properties: {
    email?: string
    firstname?: string
    lastname?: string
    [key: string]: unknown
  }
  createdAt: string
  updatedAt: string
  archived: boolean
}

export interface StripeCustomerResponse {
  id: string
  object: string
  email: string
  name: string | null
  created: number
  livemode: boolean
  [key: string]: unknown
}

export interface HandleResult {
  createdCustomerIds: string[]
  processedEvents: number
}

async function fetchHubSpotContact(
  contactId: number,
  config: ConnectorConfig
): Promise<HubSpotContact> {
  const baseUrl = config.hubspotBaseUrl ?? 'https://api.hubapi.com'
  const url = `${baseUrl}/crm/v3/objects/contacts/${contactId}`
  const fetchFn = config.fetch ?? fetch

  const response = await fetchFn(url, {
    method: 'GET',
    headers: {
      Authorization: `Bearer ${config.hubspotApiKey}`,
      'Content-Type': 'application/json',
    },
  })

  if (!response.ok) {
    throw new Error(`HubSpot contact fetch failed: ${response.status} ${response.statusText} for GET ${url}`)
  }

  return response.json() as Promise<HubSpotContact>
}

async function createStripeCustomer(
  email: string,
  name: string,
  config: ConnectorConfig
): Promise<StripeCustomerResponse> {
  const url = 'https://api.stripe.com/v1/customers'
  const fetchFn = config.fetch ?? fetch

  const body = new URLSearchParams()
  body.append('email', email)
  body.append('name', name)

  const response = await fetchFn(url, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${config.stripeSecretKey}`,
      'Content-Type': 'application/x-www-form-urlencoded',
    },
    body: body.toString(),
  })

  if (!response.ok) {
    const errorText = await response.text().catch(() => '')
    throw new Error(`Stripe create customer failed: ${response.status} ${response.statusText} for POST ${url}: ${errorText}`)
  }

  return response.json() as Promise<StripeCustomerResponse>
}

export async function handle(payload: HubSpotWebhookPayload, config: ConnectorConfig): Promise<HandleResult> {
  if (!Array.isArray(payload)) {
    throw new Error('Invalid payload: expected an array of HubSpot webhook events')
  }

  if (!config.hubspotApiKey) {
    throw new Error('Missing required config: hubspotApiKey')
  }
  if (!config.stripeSecretKey) {
    throw new Error('Missing required config: stripeSecretKey')
  }

  const createdCustomerIds: string[] = []
  let processedEvents = 0

  for (const event of payload) {
    if (
      event.propertyName === 'lifecyclestage' &&
      event.propertyValue === 'customer' &&
      event.objectTypeId === '0-1'
    ) {
      processedEvents++

      const contact = await fetchHubSpotContact(event.objectId, config)

      const email = contact.properties.email
      if (!email) {
        throw new Error(`Contact ${event.objectId} has no email address`)
      }

      const firstName = contact.properties.firstname ?? ''
      const lastName = contact.properties.lastname ?? ''
      const fullName = [firstName, lastName].filter(Boolean).join(' ') || email

      const stripeCustomer = await createStripeCustomer(email, fullName, config)
      createdCustomerIds.push(stripeCustomer.id)
    }
  }

  return { createdCustomerIds, processedEvents }
}

import { describe, it, expect, vi, beforeEach } from 'vitest'
import { handle, ConnectorConfig, HubSpotWebhookPayload, HubSpotWebhookEvent } from './connector'
import {
  SOURCE_EXAMPLE,
  TARGET_ENDPOINTS,
  contractFetch,
  fakeFetch,
  jsonResponse,
  RecordedCall,
} from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const payload = [SOURCE_EXAMPLE] as unknown as HubSpotWebhookPayload
    const config: ConnectorConfig = {
      hubspotApiKey: 'test-hubspot-key',
      stripeSecretKey: 'sk_test_stripe_key',
      fetch,
    }
    // The contract test only mocks Stripe endpoint; HubSpot contact fetch will fail
    // but we verify the Stripe call is attempted
    try {
      await handle(payload, config)
    } catch (e) {
      // Expected to fail on HubSpot fetch since contractFetch only mocks Stripe
    }
    expect(calls.length).toBeGreaterThan(0)
    const stripeCall = calls.find((c) => c.url === 'https://api.stripe.com/v1/customers')
    expect(stripeCall).toBeDefined()
    expect(stripeCall?.method).toBe('POST')
  })
})

describe('handle', () => {
  let baseConfig: ConnectorConfig
  let hubspotContactResponse: Record<string, unknown>

  beforeEach(() => {
    hubspotContactResponse = {
      id: '987654',
      properties: {
        email: 'jennyrosen@example.com',
        firstname: 'Jenny',
        lastname: 'Rosen',
      },
      createdAt: '2024-01-01T00:00:00Z',
      updatedAt: '2024-01-01T00:00:00Z',
      archived: false,
    }
    baseConfig = {
      hubspotApiKey: 'test-hubspot-key',
      stripeSecretKey: 'sk_test_stripe_key',
    }
  })

  it('creates Stripe customer for lifecycle stage change to customer', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url === 'https://api.hubapi.com/crm/v3/objects/contacts/987654' && req.method === 'GET') {
        return jsonResponse(hubspotContactResponse)
      }
      if (req.url === 'https://api.stripe.com/v1/customers' && req.method === 'POST') {
        return jsonResponse(TARGET_ENDPOINTS[0].response, 201)
      }
      return jsonResponse({ error: 'not found' }, 404)
    })

    const payload: HubSpotWebhookPayload = [
      {
        ...SOURCE_EXAMPLE,
        objectId: 987654,
      },
    ]

    const result = await handle(payload, { ...baseConfig, fetch })

    expect(result.createdCustomerIds).toEqual(['cus_NffrFeUfNV2Hib'])
    expect(result.processedEvents).toBe(1)

    expect(calls).toHaveLength(2)
    expect(calls[0].url).toBe('https://api.hubapi.com/crm/v3/objects/contacts/987654')
    expect(calls[0].method).toBe('GET')
    expect(calls[0].headers.get('authorization')).toBe('Bearer test-hubspot-key')

    expect(calls[1].url).toBe('https://api.stripe.com/v1/customers')
    expect(calls[1].method).toBe('POST')
    expect(calls[1].headers.get('authorization')).toBe('Bearer sk_test_stripe_key')
    expect(calls[1].json).toEqual({
      email: 'jennyrosen@example.com',
      name: 'Jenny Rosen',
    })
  })

  it('concatenates firstname and lastname for Stripe name', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('/crm/v3/objects/contacts/') && req.method === 'GET') {
        return jsonResponse({
          ...hubspotContactResponse,
          properties: { email: 'test@example.com', firstname: 'John', lastname: 'Doe' },
        })
      }
      if (req.url === 'https://api.stripe.com/v1/customers' && req.method === 'POST') {
        return jsonResponse({ ...TARGET_ENDPOINTS[0].response, id: 'cus_new', name: 'John Doe' }, 201)
      }
      return jsonResponse({ error: 'not found' }, 404)
    })

    const payload: HubSpotWebhookPayload = [{ ...SOURCE_EXAMPLE, objectId: 123 }]

    await handle(payload, { ...baseConfig, fetch })

    const stripeCall = calls.find((c) => c.url === 'https://api.stripe.com/v1/customers')
    expect(stripeCall?.json).toEqual({ email: 'test@example.com', name: 'John Doe' })
  })

  it('uses email as name when firstname and lastname are missing', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('/crm/v3/objects/contacts/') && req.method === 'GET') {
        return jsonResponse({
          ...hubspotContactResponse,
          properties: { email: 'noname@example.com' },
        })
      }
      if (req.url === 'https://api.stripe.com/v1/customers' && req.method === 'POST') {
        return jsonResponse({ ...TARGET_ENDPOINTS[0].response, id: 'cus_new', name: 'noname@example.com' }, 201)
      }
      return jsonResponse({ error: 'not found' }, 404)
    })

    const payload: HubSpotWebhookPayload = [{ ...SOURCE_EXAMPLE, objectId: 123 }]

    await handle(payload, { ...baseConfig, fetch })

    const stripeCall = calls.find((c) => c.url === 'https://api.stripe.com/v1/customers')
    expect(stripeCall?.json).toEqual({ email: 'noname@example.com', name: 'noname@example.com' })
  })

  it('throws when contact has no email', async () => {
    const { fetch } = fakeFetch((req) => {
      if (req.url.includes('/crm/v3/objects/contacts/') && req.method === 'GET') {
        return jsonResponse({
          ...hubspotContactResponse,
          properties: { firstname: 'No', lastname: 'Email' },
        })
      }
      return jsonResponse({ error: 'not found' }, 404)
    })

    const payload: HubSpotWebhookPayload = [{ ...SOURCE_EXAMPLE, objectId: 123 }]

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow('Contact 123 has no email address')
  })

  it('throws when hubspotApiKey is missing', async () => {
    const payload: HubSpotWebhookPayload = [SOURCE_EXAMPLE as unknown as HubSpotWebhookEvent]
    await expect(handle(payload, { stripeSecretKey: 'sk_test' })).rejects.toThrow('Missing required config: hubspotApiKey')
  })

  it('throws when stripeSecretKey is missing', async () => {
    const payload: HubSpotWebhookPayload = [SOURCE_EXAMPLE as unknown as HubSpotWebhookEvent]
    await expect(handle(payload, { hubspotApiKey: 'test' })).rejects.toThrow('Missing required config: stripeSecretKey')
  })

  it('throws when payload is not an array', async () => {
    await expect(handle({} as unknown as HubSpotWebhookPayload, baseConfig)).rejects.toThrow(
      'Invalid payload: expected an array of HubSpot webhook events'
    )
  })

  it('ignores events that are not lifecycle stage changes to customer', async () => {
    const { fetch, calls } = fakeFetch((req) => jsonResponse({ error: 'not found' }, 404))

    const payload: HubSpotWebhookPayload = [
      { ...SOURCE_EXAMPLE, propertyName: 'other_property', propertyValue: 'value' },
      { ...SOURCE_EXAMPLE, propertyValue: 'lead' },
      { ...SOURCE_EXAMPLE, objectTypeId: '0-2' },
    ]

    const result = await handle(payload, { ...baseConfig, fetch })

    expect(result.createdCustomerIds).toEqual([])
    expect(result.processedEvents).toBe(0)
    expect(calls).toHaveLength(0)
  })

  it('throws on HubSpot API error', async () => {
    const { fetch } = fakeFetch((req) => {
      if (req.url.includes('/crm/v3/objects/contacts/') && req.method === 'GET') {
        return jsonResponse({ error: 'Not found' }, 404)
      }
      return jsonResponse({ error: 'not found' }, 404)
    })

    const payload: HubSpotWebhookPayload = [{ ...SOURCE_EXAMPLE, objectId: 999 }]

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow(
      'HubSpot contact fetch failed: 404 Not Found for GET https://api.hubapi.com/crm/v3/objects/contacts/999'
    )
  })

  it('throws on Stripe API error', async () => {
    const { fetch } = fakeFetch((req) => {
      if (req.url.includes('/crm/v3/objects/contacts/') && req.method === 'GET') {
        return jsonResponse(hubspotContactResponse)
      }
      if (req.url === 'https://api.stripe.com/v1/customers' && req.method === 'POST') {
        return jsonResponse({ error: { message: 'Email already exists', type: 'invalid_request_error' } }, 400)
      }
      return jsonResponse({ error: 'not found' }, 404)
    })

    const payload: HubSpotWebhookPayload = [{ ...SOURCE_EXAMPLE, objectId: 987654 }]

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow(
      'Stripe create customer failed: 400 Bad Request for POST https://api.stripe.com/v1/customers'
    )
  })

  it('uses custom hubspotBaseUrl when provided', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url === 'https://custom.hubspot.com/crm/v3/objects/contacts/987654' && req.method === 'GET') {
        return jsonResponse(hubspotContactResponse)
      }
      if (req.url === 'https://api.stripe.com/v1/customers' && req.method === 'POST') {
        return jsonResponse(TARGET_ENDPOINTS[0].response, 201)
      }
      return jsonResponse({ error: 'not found' }, 404)
    })

    const payload: HubSpotWebhookPayload = [{ ...SOURCE_EXAMPLE, objectId: 987654 }]

    await handle(payload, { ...baseConfig, hubspotBaseUrl: 'https://custom.hubspot.com', fetch })

    const hubspotCall = calls.find((c) => c.url.includes('/crm/v3/objects/contacts/'))
    expect(hubspotCall?.url).toBe('https://custom.hubspot.com/crm/v3/objects/contacts/987654')
  })

  it('processes multiple events in one payload', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('/crm/v3/objects/contacts/') && req.method === 'GET') {
        const id = req.url.split('/').pop()
        return jsonResponse({
          ...hubspotContactResponse,
          id,
          properties: { email: `user${id}@example.com`, firstname: 'User', lastname: id },
        })
      }
      if (req.url === 'https://api.stripe.com/v1/customers' && req.method === 'POST') {
        return jsonResponse({ ...TARGET_ENDPOINTS[0].response, id: `cus_${Date.now()}` }, 201)
      }
      return jsonResponse({ error: 'not found' }, 404)
    })

    const payload: HubSpotWebhookPayload = [
      { ...SOURCE_EXAMPLE, objectId: 111, eventId: 1 },
      { ...SOURCE_EXAMPLE, objectId: 222, eventId: 2 },
      { ...SOURCE_EXAMPLE, propertyValue: 'lead', objectId: 333, eventId: 3 }, // should be ignored
    ]

    const result = await handle(payload, { ...baseConfig, fetch })

    expect(result.createdCustomerIds).toHaveLength(2)
    expect(result.processedEvents).toBe(2)
    expect(calls.filter((c) => c.url === 'https://api.stripe.com/v1/customers')).toHaveLength(2)
  })
})

// Written by patchbay from the API documentation. Regenerated on every attempt, do not edit.
// Source: https://developers.hubspot.com/docs/apps/legacy-apps/private-apps/build-with-projects/configure-webhooks
// Source: https://docs.stripe.com/api/customers/create

/** Example payload of the source event, as documented. */
export const SOURCE_EXAMPLE = {
  "appId": 3715530,
  "eventId": 100,
  "subscriptionId": 2764026,
  "portalId": 123456,
  "occurredAt": 1723651850844,
  "subscriptionType": "object.propertyChange",
  "attemptNumber": 0,
  "objectId": 987654,
  "changeSource": "CRM",
  "objectTypeId": "0-1",
  "propertyName": "lifecyclestage",
  "propertyValue": "customer",
  "isSensitive": false
}

export interface DocumentedEndpoint {
  method: string
  /** As documented; may contain placeholders such as {id}, :id, <id> or a region host like usX. */
  url: string
  response: unknown
}

/** Target endpoints the connector may call, in the documented order, with their documented responses. */
export const TARGET_ENDPOINTS: DocumentedEndpoint[] = [
  {
    "method": "POST",
    "url": "https://api.stripe.com/v1/customers",
    "response": {
      "id": "cus_NffrFeUfNV2Hib",
      "object": "customer",
      "email": "jennyrosen@example.com",
      "name": "Jenny Rosen",
      "created": 1680893993,
      "livemode": false
    }
  }
]

export interface RecordedCall {
  method: string
  url: string
  /** The request body exactly as sent (usually a JSON string). */
  body: string | undefined
  /** The body parsed as JSON, or undefined when it is not JSON. */
  json: unknown
  headers: Headers
}

/** The documented endpoint a request matches, placeholders and region subdomains included. */
export function findEndpoint(method: string, url: string): DocumentedEndpoint | undefined {
  return TARGET_ENDPOINTS.find((endpoint) => endpoint.method === method.toUpperCase() && urlMatches(endpoint.url, url))
}

/**
 * A fake fetch that answers every documented endpoint with its documented response and
 * rejects anything else. Use it in the contract test:
 *
 *   const { fetch, calls } = contractFetch()
 *   await handle(SOURCE_EXAMPLE as MyInput, { ...config, fetch })
 *   expect(calls.length).toBeGreaterThan(0)
 */
export function contractFetch(): { fetch: typeof fetch; calls: RecordedCall[] } {
  return fakeFetch((request) => {
    const endpoint = findEndpoint(request.method, request.url)
    if (!endpoint) throw new Error(`contract: ${request.method} ${request.url} is not a documented endpoint`)
    return jsonResponse(endpoint.response)
  })
}

/**
 * A correctly typed fake fetch for every other test. The handler receives the recorded
 * request: { method, url, body (string as sent), json (parsed body), headers (Headers) }.
 *
 *   const { fetch, calls } = fakeFetch((req) => req.url.endsWith('/deals') ? jsonResponse({ id: 1 }, 201) : jsonResponse({}, 404))
 */
export function fakeFetch(
  handler: (request: RecordedCall) => Response | Promise<Response>,
): { fetch: typeof fetch; calls: RecordedCall[] } {
  const calls: RecordedCall[] = []
  const fake = async (input: string | URL | Request, init: RequestInit = {}): Promise<Response> => {
    const url = input instanceof Request ? input.url : String(input)
    const method = (init.method ?? (input instanceof Request ? input.method : 'GET')).toUpperCase()
    const body = typeof init.body === 'string' ? init.body : init.body == null ? undefined : String(init.body)
    const call: RecordedCall = { method, url, body, json: parseJson(body), headers: new Headers(init.headers) }
    calls.push(call)
    return handler(call)
  }
  return { fetch: fake as typeof fetch, calls }
}

const STATUS_TEXT: Record<number, string> = {
  200: 'OK', 201: 'Created', 202: 'Accepted', 204: 'No Content',
  400: 'Bad Request', 401: 'Unauthorized', 403: 'Forbidden', 404: 'Not Found', 409: 'Conflict',
  422: 'Unprocessable Entity', 429: 'Too Many Requests',
  500: 'Internal Server Error', 502: 'Bad Gateway', 503: 'Service Unavailable',
}

/** A JSON Response with the standard status text, e.g. jsonResponse({ error: 'nope' }, 401) -> "401 Unauthorized". */
export function jsonResponse(body: unknown, status = 200): Response {
  const init = { status, statusText: STATUS_TEXT[status] ?? '', headers: { 'Content-Type': 'application/json' } }
  return new Response(status === 204 ? null : JSON.stringify(body), init)
}

function parseJson(raw: string | undefined): unknown {
  if (raw === undefined) return undefined
  try {
    return JSON.parse(raw)
  } catch {
    return undefined
  }
}

function urlMatches(template: string, actual: string): boolean {
  const t = splitUrl(template)
  const a = splitUrl(actual)
  if (!t || !a) return false
  const tHost = t.host.split('.')
  const aHost = a.host.split('.')
  if (tHost.slice(-2).join('.') !== aHost.slice(-2).join('.')) return false
  const tPath = t.path.replace(/\/+$/, '').split('/')
  const aPath = a.path.replace(/\/+$/, '').split('/')
  if (tPath.length !== aPath.length) return false
  return tPath.every((segment, i) => isPlaceholder(segment) || segment === aPath[i])
}

function splitUrl(url: string): { host: string; path: string } | null {
  const match = url.match(/^https?:\/\/([^/?#]+)([^?#]*)/i)
  return match ? { host: (match[1] ?? '').toLowerCase(), path: match[2] || '/' } : null
}

function isPlaceholder(segment: string): boolean {
  return /^\{[^}]+\}$|^:[A-Za-z_]\w*$|^<[^>]+>$/.test(segment)
}

export interface ConnectorConfig {
  /** HubSpot private app access token or API key for CRM API calls. */
  hubspotApiKey: string
  /** Base URL for HubSpot API. Defaults to 'https://api.hubapi.com'. */
  hubspotBaseUrl?: string
  /** Stripe secret key for Bearer authentication. */
  stripeSecretKey: string
  /** Injected fetch for testing. */
  fetch?: typeof fetch
}

export interface HubSpotWebhookEvent {
  appId: number
  eventId: number
  subscriptionId: number
  portalId: number
  occurredAt: number
  subscriptionType: string
  attemptNumber: number
  objectId: number
  changeSource: string
  objectTypeId: string
  propertyName: string
  propertyValue: string
  isSensitive: boolean
}

export type HubSpotWebhookPayload = HubSpotWebhookEvent[]

export interface HubSpotContact {
  id: string
  properties: {
    email?: string
    firstname?: string
    lastname?: string
    [key: string]: unknown
  }
  createdAt: string
