async function fetchHubSpotContact(
  contactId: number,
  config: ConnectorConfig
): Promise<HubSpotContact> {
  const baseUrl = config.hubspotBaseUrl ?? 'https://api.hubapi.com'
  const url = `${baseUrl}/crm/v3/objects/contacts/${contactId}`
  const fetchFn = config.fetch ?? fetch

  const response = await fetchFn(url, {
    method: 'GET',
    headers: {
      Authorization: `Bearer ${config.hubspotApiKey}`,
      'Content-Type': 'application/json',
    },
  })

  if (!response.ok) {
    throw new Error(`HubSpot contact fetch failed: ${response.status} ${response.statusText} for GET ${url}`)
  }

  return response.json() as Promise<HubSpotContact>
}

async function createStripeCustomer(
  email: string,
  name: string,
  config: ConnectorConfig
): Promise<StripeCustomerResponse> {
  const url = 'https://api.stripe.com/v1/customers'
  const fetchFn = config.fetch ?? fetch

  const body = new URLSearchParams()
  body.append('email', email)
  body.append('name', name)

  const response = await fetchFn(url, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${config.stripeSecretKey}`,
      'Content-Type': 'application/x-www-form-urlencoded',
    },
    body: body.toString(),
  })

  if (!response.ok) {
    const errorText = await response.text().catch(() => '')
    throw new Error(`Stripe create customer failed: ${response.status} ${response.statusText} for POST ${url}: ${errorText}`)
  }

  return response.json() as Promise<StripeCustomerResponse>
}

export async function handle(payload: HubSpotWebhookPayload, config: ConnectorConfig): Promise<HandleResult> {
  if (!Array.isArray(payload)) {
    throw new Error('Invalid payload: expected an array of HubSpot webhook events')
  }

  if (!config.hubspotApiKey) {
    throw new Error('Missing required config: hubspotApiKey')
  }
  if (!config.stripeSecretKey) {
    throw new Error('Missing required config: stripeSecretKey')
  }

  const createdCustomerIds: string[] = []
  let processedEvents = 0

  for (const event of payload) {
    if (
      event.propertyName === 'lifecyclestage' &&
      event.propertyValue === 'customer' &&
      event.objectTypeId === '0-1'
    ) {
      processedEvents++

      const contact = await fetchHubSpotContact(event.objectId, config)

      const email = contact.properties.email
      if (!email) {
        throw new Error(`Contact ${event.objectId} has no email address`)
      }

      const firstName = contact.properties.firstname ?? ''
      const lastName = contact.properties.lastname ?? ''
      const fullName = [firstName, lastName].filter(Boolean).join(' ') || email

      const stripeCustomer = await createStripeCustomer(email, fullName, config)
      createdCustomerIds.push(stripeCustomer.id)
    }
  }

  return { createdCustomerIds, processedEvents }
}

import { describe, it, expect, vi, beforeEach } from 'vitest'
import { handle, ConnectorConfig, HubSpotWebhookPayload, HubSpotWebhookEvent } from './connector'
import {
  SOURCE_EXAMPLE,
  TARGET_ENDPOINTS,
  contractFetch,
  fakeFetch,
  jsonResponse,
  RecordedCall,
} from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url === 'https://api.hubapi.com/crm/v3/objects/contacts/987654' && req.method === 'GET') {
        return jsonResponse({
          id: '987654',
          properties: {
            email: 'jennyrosen@example.com',
            firstname: 'Jenny',
